#include "apex/tracking.hpp"
#include <nlohmann/json.hpp>
#include <algorithm>
#include <cmath>
#include <fstream>
#include <stdexcept>
namespace apex {namespace {
void validate(const TrackingOptions& o){auto axis=[](const TrackingAxis& a){return std::isfinite(a.gain)&&a.gain>=0&&a.gain<=10&&std::isfinite(a.smoothingMs)&&a.smoothingMs>=0&&a.smoothingMs<=500&&std::isfinite(a.maxSpeed)&&a.maxSpeed>=10&&a.maxSpeed<=1000;};if(static_cast<int>(o.activationMode)<0||static_cast<int>(o.activationMode)>1||static_cast<int>(o.activationKey)<0||static_cast<int>(o.activationKey)>5||!axis(o.x)||!axis(o.y)||!std::isfinite(o.radius)||o.radius<20||o.radius>800||!std::isfinite(o.deadzone)||o.deadzone<0||o.deadzone>30||!std::isfinite(o.anchor)||o.anchor<.1f||o.anchor>.9f||!std::isfinite(o.maxAgeMs)||o.maxAgeMs<50||o.maxAgeMs>500||!std::isfinite(o.reacquireMs)||o.reacquireMs<0||o.reacquireMs>500)throw std::runtime_error("Invalid tracking settings");}
float iou(const EnemyBox& a,const EnemyBox& b){float intersection=std::max(0.f,std::min(a.x2,b.x2)-std::max(a.x1,b.x1))*std::max(0.f,std::min(a.y2,b.y2)-std::max(a.y1,b.y1));float sum=(a.x2-a.x1)*(a.y2-a.y1)+(b.x2-b.x1)*(b.y2-b.y1)-intersection;return sum>0?intersection/sum:0;}
bool validBox(const EnemyBox& b){return std::isfinite(b.x1)&&std::isfinite(b.y1)&&std::isfinite(b.x2)&&std::isfinite(b.y2)&&std::isfinite(b.score)&&b.score>=0&&b.score<=1&&b.x1>=0&&b.y1>=0&&b.x2<=1&&b.y2<=1&&b.x2>b.x1&&b.y2>b.y1;}
int axisStep(float error,const TrackingAxis& axis,float deadzone,float dt,float& velocity,float& remainder){if(!axis.enabled||std::abs(error)<=deadzone){velocity=remainder=0;return 0;}if(velocity*error<0)velocity=remainder=0;float desired=std::clamp(error*axis.gain,-axis.maxSpeed,axis.maxSpeed);float alpha=axis.smoothingMs>0?1-std::exp(-dt*1000/axis.smoothingMs):1;velocity+=(desired-velocity)*alpha;float amount=velocity*dt+remainder;int step=std::clamp(static_cast<int>(amount),-12,12);remainder=std::clamp(amount-step,-1.f,1.f);return step;}
}
const char* trackingActivationName(TrackingActivationKey key){static const char* names[]={"Right mouse","Mouse 4 (side)","Mouse 5 (side)","Left Alt","Left Shift","Left Ctrl"};int n=static_cast<int>(key);return n>=0&&n<6?names[n]:"Invalid key";}
void TrackingActivator::reset(){latched_=false;previousDown_=true;pendingUntil_=-1;state_={};}
void TrackingActivator::requestStart(double now,const TrackingOptions& options){reset();if(!std::isfinite(now)||options.activationMode!=TrackingActivationMode::Toggle)return;mode_=options.activationMode;key_=options.activationKey;configured_=true;pendingUntil_=now+10;state_.pending=true;state_.status="START requested: switch to selected game within 10 seconds";}
TrackingActivationResult TrackingActivator::update(const TrackingActivationInput& input,const TrackingOptions& options){bool wasActive=state_.active;state_={};auto finish=[&](bool active,const std::string& status){state_.active=active;state_.started=active&&!wasActive;state_.pending=pendingUntil_>=0;state_.status=status;return state_;};
 if(!configured_||mode_!=options.activationMode||key_!=options.activationKey){reset();mode_=options.activationMode;key_=options.activationKey;configured_=true;previousDown_=input.keyDown;wasActive=false;}
 if(!std::isfinite(input.now)||!options.armed||!input.ready||input.emergency){latched_=false;pendingUntil_=-1;previousDown_=input.keyDown;return finish(false,input.emergency?"F9 stop":!options.armed?"DISARMED":!input.ready?"Blocked: check game window, live capture and model":"Invalid activation clock");}
 if(pendingUntil_>=0){if(input.now>pendingUntil_){pendingUntil_=-1;latched_=false;previousDown_=input.keyDown;return finish(false,"START expired: click START LOCK again");}if(!input.focused){previousDown_=input.keyDown;return finish(false,"START pending: switch to selected game (10-second window)");}pendingUntil_=-1;latched_=true;previousDown_=input.keyDown;return finish(true,"ACTIVE: click STOP or press activation key again; F9 disarms");}
 if(!input.focused){latched_=false;previousDown_=input.keyDown;return finish(false,options.activationMode==TrackingActivationMode::Toggle?"Inactive: selected game not focused; toggle lock cancelled":"Inactive: selected game not focused");}
 bool pressed=input.keyDown&&!previousDown_;previousDown_=input.keyDown;if(options.activationMode==TrackingActivationMode::Hold)return finish(input.keyDown,std::string(input.keyDown?"ACTIVE: holding ":"Hold ")+trackingActivationName(options.activationKey));if(pressed)latched_=!latched_;return finish(latched_,std::string(latched_?"ACTIVE: press again to stop | ":"Press to start | ")+trackingActivationName(options.activationKey));
}
void applyFastLockPreset(TrackingOptions& o){o.x={true,8,0,800};o.y={true,8,0,800};o.deadzone=1;o.reacquireMs=250;o.armed=false;}
void TargetTracker::reset(){locked_=available_=false;lastSequence_=0;lastFrame_=lastTick_=seenAt_=-1;width_=height_=0;velocityX_=velocityY_=remainderX_=remainderY_=0;}
TrackingResult TargetTracker::update(const std::vector<EnemyBox>& boxes,const TrackingContext& c,const TrackingOptions& o){
 TrackingResult result;try{validate(o);}catch(const std::exception& e){reset();result.status=e.what();return result;}
 if(!std::isfinite(c.now)||!std::isfinite(c.frameTime)||!std::isfinite(c.width)||!std::isfinite(c.height)||c.width<=0||c.height<=0){reset();result.status="Waiting for selected game geometry";return result;}
 if(width_!=c.width||height_!=c.height){reset();width_=c.width;height_=c.height;}
 auto pause=[&]{available_=false;velocityX_=velocityY_=remainderX_=remainderY_=0;lastTick_=c.now;if(o.reacquireMs<=0||seenAt_<0||c.now<seenAt_||(c.now-seenAt_)*1000>o.reacquireMs)locked_=false;result.reacquiring=locked_;if(locked_)result.targetId=identity_;};
 if(c.frameTime<=0){reset();result.status="Waiting for first model detection result";return result;}
 result.ageMs=float((c.now-c.frameTime)*1000);if(!c.live){reset();result.status="Live camera capture required; no input from recordings";return result;}
 if(result.ageMs<0||result.ageMs>o.maxAgeMs){pause();result.status=result.reacquiring?"Stale result: identity held briefly; movement paused":"Capture/model result stale; mouse output stopped";return result;}
 if(locked_&&(c.now-seenAt_)*1000>o.reacquireMs&&!available_)locked_=false;
 // Association uses actual new measurements, never a projected or held display box.
 auto affinity=[&](const EnemyBox& b){float overlap=iou(box_,b);if(overlap>=.15f)return 1+overlap;float oldW=(box_.x2-box_.x1)*c.width,oldH=(box_.y2-box_.y1)*c.height,newW=(b.x2-b.x1)*c.width,newH=(b.y2-b.y1)*c.height;float dx=((b.x1+b.x2)-(box_.x1+box_.x2))*.5f*c.width,dy=((b.y1+b.y2)-(box_.y1+box_.y2))*.5f*c.height;float gate=std::clamp(.6f*std::max(oldW,oldH),10.f,60.f),distance=std::sqrt(dx*dx+dy*dy);if(newW<oldW*.5f||newW>oldW*2||newH<oldH*.5f||newH>oldH*2||distance>gate)return 0.f;return .1f+.8f*(1-distance/gate);};
 bool newFrame=c.sequence!=lastSequence_||c.frameTime!=lastFrame_;
 if(newFrame){const EnemyBox* nearest=nullptr;const EnemyBox* associated=nullptr;float bestDistance=o.radius*o.radius,bestAffinity=0;for(const auto& box:boxes){if(!validBox(box))continue;float x=(box.x1+box.x2)*.5f*c.width-c.width*.5f,y=(box.y1+(box.y2-box.y1)*o.anchor)*c.height-c.height*.5f,distance=x*x+y*y;if(distance>o.radius*o.radius)continue;if(distance<=bestDistance){nearest=&box;bestDistance=distance;}float match=locked_?affinity(box):0;if(match>bestAffinity){associated=&box;bestAffinity=match;}}
  auto selected=associated?associated:nearest;if(selected){if(!associated){identity_=nextIdentity_++;velocityX_=velocityY_=remainderX_=remainderY_=0;}box_=*selected;locked_=available_=true;seenAt_=c.now;}else pause();lastSequence_=c.sequence;lastFrame_=c.frameTime;}
 if(locked_&&available_){result.target=true;result.targetId=identity_;result.x=(box_.x1+box_.x2)*.5f*c.width;result.y=(box_.y1+(box_.y2-box_.y1)*o.anchor)*c.height;result.errorX=result.x-c.width*.5f;result.errorY=result.y-c.height*.5f;if(result.errorX*result.errorX+result.errorY*result.errorY>o.radius*o.radius){locked_=available_=false;result.target=false;}}
 result.reacquiring=locked_&&!available_;if(result.reacquiring)result.targetId=identity_;
 bool axes=(o.x.enabled&&o.x.gain>0)||(o.y.enabled&&o.y.gain>0);bool engaged=o.armed&&c.focused&&c.hold&&c.emergencyAvailable&&result.target&&axes;float dt=lastTick_>=0?float(std::clamp(c.now-lastTick_,0.,.05)):std::isfinite(c.deltaSeconds)?std::clamp(c.deltaSeconds,0.f,.05f):0;lastTick_=c.now;result.engaged=engaged;
 if(!engaged){velocityX_=velocityY_=remainderX_=remainderY_=0;result.status=!o.armed?"Disarmed; configure and explicitly arm":!c.emergencyAvailable?"Emergency hotkey unavailable":!c.focused?"Selected Apex window is not focused":!c.hold?"Activation inactive; use configured key/button or START LOCK":result.reacquiring?"Brief detection gap: identity held; movement paused":!result.target?"No detected character inside circle":!axes?"Tracking axes disabled or zero response":"Paused";return result;}
 result.moveX=axisStep(result.errorX,o.x,o.deadzone,dt,velocityX_,remainderX_);result.moveY=axisStep(result.errorY,o.y,o.deadzone,dt,velocityY_,remainderY_);result.status=std::abs(result.errorX)<=o.deadzone&&std::abs(result.errorY)<=o.deadzone?"LOCKED: detected character centered (deadzone)":"LOCKED: following detected character; game response unverified";return result;
}
bool saveTrackingOptions(const std::filesystem::path& path,const TrackingOptions& o,std::string& error){try{validate(o);auto axis=[](const TrackingAxis& a){return nlohmann::json{{"enabled",a.enabled},{"gain",a.gain},{"smoothing_ms",a.smoothingMs},{"max_speed",a.maxSpeed}};};nlohmann::json j={{"version",1},{"x",axis(o.x)},{"y",axis(o.y)},{"radius",o.radius},{"deadzone",o.deadzone},{"anchor",o.anchor},{"max_age_ms",o.maxAgeMs},{"reacquire_ms",o.reacquireMs},{"show_fov",o.showFov},{"activation_mode",static_cast<int>(o.activationMode)},{"activation_key",static_cast<int>(o.activationKey)}};std::filesystem::create_directories(path.parent_path());std::ofstream f(path);f<<j.dump(2);f.flush();if(!f)throw std::runtime_error("Tracking setup write failed");error.clear();return true;}catch(const std::exception& e){error=e.what();return false;}}
bool loadTrackingOptions(const std::filesystem::path& path,TrackingOptions& o,std::string& error){try{if(std::filesystem::file_size(path)>16384)throw std::runtime_error("Tracking setup too large");nlohmann::json j;std::ifstream(path)>>j;if(j.at("version")!=1)throw std::runtime_error("Unsupported tracking setup");TrackingOptions next;auto axis=[](const nlohmann::json& a){TrackingAxis result;result.enabled=a.at("enabled");result.gain=a.at("gain");result.smoothingMs=a.at("smoothing_ms");result.maxSpeed=a.at("max_speed");return result;};next.x=axis(j.at("x"));next.y=axis(j.at("y"));next.radius=j.at("radius");next.deadzone=j.at("deadzone");next.anchor=j.at("anchor");next.maxAgeMs=j.at("max_age_ms");next.reacquireMs=j.value("reacquire_ms",250.f);next.showFov=j.at("show_fov");next.activationMode=static_cast<TrackingActivationMode>(j.value("activation_mode",0));next.activationKey=static_cast<TrackingActivationKey>(j.value("activation_key",0));validate(next);next.armed=false;o=next;error.clear();return true;}catch(const std::exception& e){error=e.what();return false;}}
}
